package vn.gk.logistics.validation;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class OrderInputsTest {
 private final LocalDateTime now=LocalDateTime.of(2026,11,22,10,0);
 Map<String,Object> good(){return new HashMap<>(Map.ofEntries(Map.entry("pickupName","  Nguyễn  Minh An "),Map.entry("customerName","Cửa hàng Bánh 123"),Map.entry("pickupPhone","+84 903 000 001"),Map.entry("phone","0903000002"),Map.entry("pickupAddress","50 Tên Lửa, Bình Tân"),Map.entry("address","100 Nguyễn Văn Cừ, Quận 5"),Map.entry("pickupLat",10.7),Map.entry("pickupLng",106.6),Map.entry("lat",10.8),Map.entry("lng",106.7),Map.entry("weightKg",50),Map.entry("volumeM3",.05),Map.entry("goodsDescription","2 thùng tài liệu"),Map.entry("goodsType","documents"),Map.entry("pickupFrom","2026-11-23T08:00"),Map.entry("pickupTo","2026-11-23T12:00"),Map.entry("deliveryFrom","2026-11-23T13:00"),Map.entry("deliveryTo","2026-11-23T20:00")));}
 @Test void normalizesHumanNamesAndVietnamesePhones(){var out=OrderInputs.validate(good(),now);assertEquals("Nguyễn Minh An",out.get("pickupName"));assertEquals("0903000001",out.get("pickupPhone"));assertEquals("",out.get("note"));assertEquals("0903000001",OrderInputs.phone("+84\u00a0903000001"));assertEquals("Nguyễn Minh An",OrderInputs.name("\u00a0Nguyễn\u00a0Minh An\u00a0"));assertEquals("Cửa hàng Bánh 123",out.get("customerName"));}
 @Test void rejectsMissingMandatoryFieldsAndReturnsFieldNames(){for(var key:List.of("pickupName","phone","pickupPhone","address","weightKg","volumeM3","goodsDescription","pickupFrom")){var body=good();body.remove(key);assertTrue(assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now)).fields.containsKey(key),key);}}
 @Test void rejectsInvalidPhoneAndWhitespaceName(){for(String phone:List.of("123","abcdefghij","09030000001")){var body=good();body.put("phone",phone);assertTrue(assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now)).fields.containsKey("phone"));}assertThrows(IllegalArgumentException.class,()->OrderInputs.name("123"));assertThrows(IllegalArgumentException.class,()->OrderInputs.name(" "));}
 @Test void enforcesFiniteWeightVolumeCoordinatesAndTextLengths(){for(var pair:List.of(Map.entry("weightKg",0),Map.entry("weightKg",10001),Map.entry("volumeM3",0),Map.entry("lat",91),Map.entry("lng",Double.NaN),Map.entry("goodsDescription","x".repeat(501)),Map.entry("note","x".repeat(1001)))){var body=good();body.put(pair.getKey(),pair.getValue());assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now));}}
 @Test void rejectsInvalidOrReversedOutsideShiftAndExpiredWindows(){for(String to:List.of("2026-02-30T20:00","2026-11-23T07:00","2026-11-23T21:00","2026-11-23T08:00","2026-11-24T12:00","2026-11-21T20:00")){var body=good();body.put("pickupTo",to);assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now),to);}}
 @Test void deliveryCannotEndBeforePickupBecomesPossible(){var body=good();body.put("deliveryFrom","2026-11-22T11:00");body.put("deliveryTo","2026-11-22T20:00");assertTrue(assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now)).fields.containsKey("deliveryTo"));}
 @Test void cutoffAndNinetyDayBoundAreEnforced(){var body=good();body.put("pickupFrom","2026-11-22T08:00");body.put("pickupTo","2026-11-22T20:00");assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now.withHour(20)));body.put("pickupFrom","2027-05-01T08:00");body.put("pickupTo","2027-05-01T20:00");assertThrows(OrderInputs.Invalid.class,()->OrderInputs.validate(body,now));}
}
